  return (
    <View className="service-card">
      <Text className="service-card__title">专属服务</Text>
      <View className="service-card__actions">
        {actions.map((action) => (
          <Text key={action} className="service-card__action">{action}</Text>
        ))}
      </View>
    </View>
  );
}
